vrml.1:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Immersive

Viewpoint { }

DEF T TimeSensor {
  cycleInterval 3
  loop TRUE
  startTime 946684800
}

DEF DRV Script {
  inputOnly   SFFloat set_f
  outputOnly  SFInt32 choice
  inputOutput SFInt32 step 0

  url "ecmascript:
function set_f (f, ts) {
  var s = Math.floor (f * 6);
  if (s == step) return;
  step = s;
  choice = s % 3;
}
"
}

Transform {
  translation -3 0 0
  children DEF SW Switch {
    whichChoice 0
    children [
      Shape {
        geometry Box { }
      }
      Shape {
        geometry Sphere { }
      }
      Shape {
        geometry Cone { }
      }
    ]
  }
}

Transform {
  translation 3 0 0
  children DEF LOD1 LOD {
    range [
      5,
      15
    ]
    children [
      Shape {
        geometry Box { }
      }
      Shape {
        geometry Sphere { }
      }
      Shape {
        geometry Cone { }
      }
    ]
  }
}

Transform {
  translation 0 3 0
  children DEF BB Billboard {
    children Shape {
      geometry Box {
        size 0.5 0.5 0.5
      }
    }
  }
}

DEF OBS Script {
  inputOutput SFInt32 sw 0
  inputOutput SFInt32 lodLevel 1

  url "ecmascript:
function noop () { }
"
}

ROUTE T.fraction_changed TO DRV.set_f
ROUTE DRV.choice TO SW.set_whichChoice
ROUTE SW.whichChoice_changed TO OBS.set_sw
ROUTE LOD1.level_changed TO OBS.set_lodLevel

